options(stringsAsFactors = FALSE)
stopifnot(getRversion() == "4.6.1")
root <- normalizePath(getwd(), mustWork = TRUE)
out <- file.path(root, "audit/manuscript_nature_health/revision_2026_09_11/consolidated_display_repair_order72k")
sel <- file.path(root, "audit/manuscript_nature_health/consolidated_display_repair_2026_09_11/integration_candidate_order72k")
record <- file.path(out, "environment_capture_recovery_001")
manifest_path <- file.path(record, "stopped_visual_owner_manifest.csv")
seal_path <- file.path(record, "stopped_visual_owner_seal.json")
stopifnot(!file.exists(manifest_path), !file.exists(seal_path))
sha <- function(p) { con <- file(p, "rb"); on.exit(close(con)); unname(unclass(as.character(openssl::sha256(con)))) }
pins <- read.csv(file.path(record, "preflight_854_rows.csv"), check.names = FALSE)
paths <- ifelse(startsWith(pins$path, "/"), pins$path, file.path(root, pins$path))
stopifnot(all(vapply(paths, sha, character(1)) == pins$expected_sha256))
files <- sort(c(list.files(out, recursive = TRUE, full.names = TRUE, all.files = TRUE), list.files(sel, recursive = TRUE, full.names = TRUE, all.files = TRUE)))
files <- files[!file.info(files)$isdir]
stopifnot(all(Sys.readlink(files) == ""), !anyDuplicated(files))
manifest <- data.frame(path = substring(files, nchar(root) + 2L), sha256 = vapply(files, sha, character(1)), bytes = file.info(files)$size)
write.csv(manifest, manifest_path, row.names = FALSE)
seal <- list(status = "STOPPED_VISUAL", gate = "REPORT018-ORDER72K-NON-S5-INTEGRATED-PREVIEW-REVIEW", canonical_promotion = FALSE, source_rehash_rows = 854L, manifest = list(path = manifest_path, sha256 = sha(manifest_path), members = nrow(manifest)), return_note = list(path = file.path(record, "stopped_visual_return.md"), sha256 = sha(file.path(record, "stopped_visual_return.md"))), capture_manifest_sha256 = sha(file.path(out, "capture_s2_attempt3/word_table_png_manifest.json")), remaining_S2_trials = 0L, consolidated_correction_renders_consumed = 0L, Word_assembly_consumed = 0L, office_QA_consumed = 0L, candidate_docx = "Not produced", lease_released = "ORDER72K-VISUAL-LEASE-002", exclusion = "This seal and its manifest are excluded from the manifest; no self hash", sealed_at_utc = format(Sys.time(), "%Y-%m-%dT%H:%M:%SZ", tz = "UTC"))
jsonlite::write_json(seal, seal_path, auto_unbox = TRUE, pretty = TRUE)
cat(jsonlite::toJSON(seal, auto_unbox = TRUE, pretty = TRUE), "\n")
